/* Все числа игры в одном месте: корабли, комнаты верфи, трассы, заказы, опыт, трофей. */
(function () {
  'use strict';
  var D = M.D = {};

  // Корабли. tanks — сколько цистерн берёт за рейс, speed м/с на самом спокойном заказе (темп заказа добавляет ещё до четверти), быстро, как гоночная машина, turn — резкость руля,
  // grip — цепкость корпуса (меньше = легче занос), armour — множитель урона грузу.
  D.SHIPS = [
    { id: 'megalul', name: 'Мегалюль', cls: 1, price: 0, tanks: 10, speed: 58, turn: 1.0, grip: 1.0, armour: 1.0, size: 1.0, hull: 0xc0432f, stripe: 0xf7f3ea, deck: 0x4e6358, house: 0xf1efe6, desc: 'Тот самый. Десять цистерн и ровный характер.' },
    { id: 'saratovets', name: 'Саратовец', cls: 1, price: 5000, tanks: 8, speed: 66, turn: 1.25, grip: 0.9, armour: 1.3, size: 0.9, hull: 0x2f8fd6, stripe: 0xffffff, deck: 0x3a4a5a, house: 0xf4f4f0, desc: 'Речной малыш: быстрый и вертлявый, но борта тонкие.' },
    { id: 'volgodon', name: 'Волго-Дон', cls: 2, price: 12000, tanks: 14, speed: 54, turn: 0.85, grip: 1.1, armour: 0.7, size: 1.12, hull: 0x3f8f5a, stripe: 0xf7f3ea, deck: 0x44504a, house: 0xe9e6dc, desc: 'Класс «река-море». Неторопливый, зато терпит удары.' },
    { id: 'extra', name: 'Экстра', cls: 2, price: 20000, tanks: 12, speed: 63, turn: 1.1, grip: 0.95, armour: 0.9, size: 1.0, hull: 0xf2b632, stripe: 0x1d2a3a, deck: 0x3a3f46, house: 0xffffff, desc: 'Экстра причаливание. Быстрый и послушный.' },
    { id: 'cruiser', name: 'Крейсер', cls: 3, price: 30000, tanks: 20, speed: 56, turn: 0.8, grip: 1.15, armour: 0.55, size: 1.3, hull: 0x4a5560, stripe: 0xc0432f, deck: 0x363b42, house: 0xdfe3e8, desc: 'Крейсер у меня! Двадцать цистерн и броня.' }
  ];
  D.shipById = function (id) { for (var i = 0; i < D.SHIPS.length; i++) if (D.SHIPS[i].id === id) return D.SHIPS[i]; return D.SHIPS[0]; };

  // Темп заезда: крейсерская скорость корабля умножается на 1 + diff × сложность заказа. Сложный заказ не только уже и круче, но и быстрее.
  D.PACE = { diff: 0.25 };
  D.pace = function (difficulty) { return 1 + D.PACE.diff * M.clamp(difficulty || 0, 0, 1); };

  // Доработки корабля: три ступени, цена растёт с классом корабля.
  D.TUNING = [
    { key: 'engine', name: 'Двигатель', desc: 'Выше крейсерская скорость.', prices: [500, 1200, 3000], fx: function (l) { return '+' + 3 * l + ' м/с'; } },
    { key: 'rudder', name: 'Руль', desc: 'Резче поворот и послушнее занос.', prices: [400, 1000, 2500], fx: function (l) { return '+' + 12 * l + '% к повороту'; } },
    { key: 'fenders', name: 'Кранцы', desc: 'Мягче удары, груз страдает меньше.', prices: [400, 1000, 2500], fx: function (l) { return '−' + 15 * l + '% урона'; } },
    { key: 'tanks', name: 'Цистерны', desc: 'Ещё по одной цистерне на палубу.', prices: [600, 1500, 3500], fx: function (l) { return '+' + l + ' к вместимости'; } }
  ];

  // Комнаты верфи, пять уровней. cost — монеты за переход на уровень i (с нулевого индекса), lvl — нужный уровень капитана, look — как комната выглядит на уровне.
  D.ROOMS = {
    office: { name: 'Контора', desc: 'Заказы и связь с портами. Выше уровень: больше заказов на доске, новые реки и трассы потруднее.',
      cost: [0, 800, 2000, 5000, 10000], lvl: [1, 2, 4, 7, 10], orders: [2, 3, 3, 4, 4], fx: function (l) { return D.ROOMS.office.orders[l - 1] + ' заказа · ' + ['Янцзы', '+ Севморпуть', '+ Малакка', '+ Босфор ночью', '+ сложные трассы'][l - 1]; },
      look: ['Голый бетон, ящик вместо стола, табурет и лампочка на проводе.', 'Настоящий стол, стул, компьютер, шкаф с папками и часы.', 'Деревянный пол, ковёр, диван, фикус и книжная полка.', 'Картины, торшер с тёплым светом, кофеварка и вентилятор.', 'Вывеска «ОАО МЕГАЛЮЛЬ», аквариум, кубки и кот на диване.'] },
    plant: { name: 'Цех', desc: 'Делает удобрение. Китайское, нормальное, чистое. Работает и пока вы в рейсе, и пока игра закрыта.',
      cost: [0, 600, 1500, 3500, 8000], lvl: [1, 2, 3, 5, 8], rate: [12, 9, 6, 4, 3], fx: function (l) { return 'цистерна за ' + D.ROOMS.plant.rate[l - 1] + ' с'; },
      look: ['Ржавый чан, ведро под капелью, тачка и обломок трубы.', 'Два медных котла, трубы по стене и мешки сырья.', 'Три котла, конвейер с бочками, факел на вышке снаружи.', 'Пульт, манометры, вытяжка и маячок.', 'Латунные обручи, гирлянда, флажки и вывеска.'] },
    store: { name: 'Склад', desc: 'Парк резервуаров. Когда он полон, цех останавливается.',
      cost: [0, 500, 1200, 3000, 7000], lvl: [1, 2, 3, 5, 7], cap: [20, 40, 70, 110, 160], fx: function (l) { return 'до ' + D.ROOMS.store.cap[l - 1] + ' цистерн'; },
      look: ['Цистерны прямо на полу, на поддонах, рядом швабра и ведро.', 'Первый стеллаж и тележка.', 'Второй стеллаж и погрузчик.', 'Третий ярус, лампы, разметка и огнетушитель.', 'Кран-балка, весы, контейнеры на палубе и вывеска.'] },
    dock: { name: 'Док', desc: 'Стапель и мастерская. Уровень дока решает, какие корабли можно купить и как глубоко их дорабатывать.',
      cost: [0, 1000, 2500, 6000, 12000], lvl: [1, 3, 5, 8, 11], cls: [1, 1, 2, 2, 3], depth: [1, 2, 2, 3, 3], fx: function (l) { return 'корабли ' + D.ROOMS.dock.cls[l - 1] + '-го класса · доработки до ' + D.ROOMS.dock.depth[l - 1] + '-й ступени'; },
      look: ['Корабль на деревянных подпорках, стремянка, ведро и бухта троса.', 'Стрела крана, верстак, покрышки и портовый кран на палубе.', 'Стальная эстакада, стенд с инструментами и бочки.', 'Прожекторы, компрессор, краски и слип к воде.', 'Спасательные круги, флажки, разметка и вывеска.'] }
  };
  // Платформа в целом хорошеет по сумме уровней комнат: ступень 1 при сумме 4, дальше каждые четыре уровня.
  D.RIG_LOOK = ['Ржавая палуба посреди океана: ни перил, ни света, бочки по углам.', 'Перила, шлюпка на балках и разметка на вертолётной площадке.', 'Свежая краска, фонари по углам, жёлтая кромка и скамейка.', 'Флагшток, зонт со столиком и кадки с кустами.', 'Гирлянда по перилам, антенна и мигающие буи.'];
  D.rigStage = function (rooms) { var s = 0; for (var k in rooms) s += rooms[k]; return M.clamp(1 + Math.floor((s - 4) / 4), 1, 5); };
  D.FILL_PRICE = 30;            // монет за цистерну, если не хочется ждать цех
  D.ORDER_EVERY = 90;           // секунд до нового заказа на доске
  D.ORDER_TTL = 15 * 60;        // секунд, сколько заказ висит на доске, потом его забирают другие
  D.ORDER_MAX = 4;

  // Трассы: палитра, сцепление с водой (зимой лёд), особенности. office — уровень конторы, с которого трасса появляется в заказах.
  D.TRACKS = [
    { id: 'summer', name: 'Янцзы', office: 1, friction: 1.0, pay: 1.0, trees: 'round', lamps: true,
      pal: { sky: 0x9fd3f0, fog: 0xc6e6f6, water: 0x2d6c86, line: 0xd7edf4, bank: 0xe6d7a8, ground: 0x7fb95c, ground2: 0x5f9a46, hill: 0x5c8f7d, tree: 0x3f9050, tree2: 0x2f7a43, trunk: 0x6a4a32, rock: 0x8c8f96, sun: 0xfff1d6, hemi: 0xcfe9ff, hemiG: 0x56704a } },
    { id: 'winter', name: 'Севморпуть', office: 2, friction: 0.62, pay: 1.3, trees: 'crystal', lamps: true,
      pal: { sky: 0xbfe0ff, fog: 0xdbedff, water: 0x3a4d68, line: 0xd9e8ff, bank: 0xdfeaf7, ground: 0xeaf3ff, ground2: 0xcfe0f5, hill: 0x8fb2d8, tree: 0x3c6f8c, tree2: 0x2a556f, trunk: 0x2d3a4a, rock: 0x9fb6cc, sun: 0xeaf2ff, hemi: 0xffffff, hemiG: 0x8da6c4 } },
    { id: 'rocks', name: 'Малакка', office: 3, friction: 0.95, pay: 1.6, trees: 'palm', lamps: false, rocks: true,
      pal: { sky: 0x8fd0ee, fog: 0xbfe6f0, water: 0x1f8f9e, line: 0xdff6f2, bank: 0xf0dca0, ground: 0x6cb85a, ground2: 0x4f9a46, hill: 0x4f8a6a, tree: 0x46a35a, tree2: 0x2f8a48, trunk: 0x8a6a42, rock: 0x7a7d86, sun: 0xfff6dc, hemi: 0xd6f0ff, hemiG: 0x4f6a3a } },
    { id: 'night', name: 'Босфор', office: 4, friction: 1.0, pay: 1.9, trees: 'round', lamps: true, night: true,
      pal: { sky: 0x101a33, fog: 0x0f1830, water: 0x0c2436, line: 0x8fb0c8, bank: 0x2a2f3a, ground: 0x1e2f3a, ground2: 0x16252e, hill: 0x121c2a, tree: 0x17313a, tree2: 0x10262e, trunk: 0x1a1f26, rock: 0x343a46, sun: 0x8fa6ff, hemi: 0x3a4878, hemiG: 0x0b1014 } }
  ];
  D.trackById = function (id) { for (var i = 0; i < D.TRACKS.length; i++) if (D.TRACKS[i].id === id) return D.TRACKS[i]; return D.TRACKS[0]; };

  // Длина заказа и его облик.
  D.LENGTHS = [{ key: 'short', name: 'Короткий', m: 2400, k: 0.8 }, { key: 'mid', name: 'Обычный', m: 3600, k: 1.0 }, { key: 'long', name: 'Дальний', m: 5400, k: 1.35 }];
  D.STATUS = [[0, 'ТАК СЕБЕ'], [120, 'ДОСТОЙНО'], [400, 'ОТЛИЧНО'], [1000, 'МЕГАЛЮЛЬ']];   // подпись к сброшенной серии дрифта по её очкам
  D.UNIT_PAY = 200;             // монет за цистерну в обычном заказе
  D.xpNeed = function (level) { return 300 * level * level; };   // квадратично, как в оригинале, но мягче: до 11-го уровня (максимум дока) около 30 заездов
  // Название трофея пишется именно так, «Питса», это не опечатка.
  D.TROPHY = { id: 'maserati', name: 'Питса 4 сыра Мазерати', price: 60000, desc: 'Коробка пиццы. Та самая, четыре сыра. Цель всей карьеры: огромная, с приоткрытой крышкой, встанет на вертолётной площадке у конторы, чтобы видно было с моря.' };
})();
